// Fresh, synthetic local account and three cards for the browser count test.
// TEST_ENV_FILE=<owned loopback env> TAB_RETURN_DIR=<private output> node ... setup|cleanup
import fs from'node:fs/promises';import path from'node:path';import{randomUUID}from'node:crypto';import{execFileSync}from'node:child_process';import{createClient}from'@supabase/supabase-js';import{createServerClient}from'@supabase/ssr';
if(process.env.TEST_ENV_FILE)process.loadEnvFile(process.env.TEST_ENV_FILE);const e=process.env;
if(e.MFA_TEST_DISPOSABLE!=='1'||[e.APP_URL,e.NEXT_PUBLIC_SUPABASE_URL,e.TEST_SQL_DATABASE_URL].some(u=>!u||new URL(u).hostname!=='127.0.0.1'))throw Error('Owned disposable loopback stack required');
const dir=path.resolve(e.TAB_RETURN_DIR??'/tmp/tab-return-check'),ledger=e.TAB_RETURN_FIXTURE??path.join(dir,'fixture.json'),sessionFile=e.TEST_SESSION_FILE??path.join(dir,'session.json');
if([ledger,sessionFile].some(f=>path.resolve(f).startsWith(process.cwd()+path.sep)))throw Error('Keep fixture sessions outside the repository');
const admin=createClient(e.NEXT_PUBLIC_SUPABASE_URL,e.SUPABASE_SECRET_KEY,{auth:{persistSession:false,autoRefreshToken:false}}),sql=q=>execFileSync('psql',['-XqAt','--dbname',e.TEST_SQL_DATABASE_URL,'-v','ON_ERROR_STOP=1'],{input:q,encoding:'utf8'}).trim();
if(process.argv[2]==='cleanup'){
 const f=JSON.parse(await fs.readFile(ledger));if(!/^[a-f0-9-]{36}$/.test(f.user))throw Error('Invalid fixture owner');const user=await admin.auth.admin.getUserById(f.user);if(user.error||!user.data.user.email.startsWith('tab-return-'))throw Error('Not this fixture account');const result=await admin.auth.admin.deleteUser(f.user);if(result.error)throw result.error;const count=sql(`select count(*) from posts where user_id='${f.user}';`);if(count!=='0')throw Error('Fixture posts remain');const gone=await admin.auth.admin.getUserById(f.user);if(!gone.error)throw Error('Fixture account remains');await fs.rm(sessionFile,{force:true});console.log(JSON.stringify({fixturePosts:0,fixtureUser:0,sessionRemoved:true}));
}else if(process.argv[2]==='setup'){
 try{await fs.access(ledger);throw Error('Preserve the existing ledger; choose a fresh output directory');}catch(error){if(error.code!=='ENOENT')throw error;}
 await fs.mkdir(path.dirname(ledger),{recursive:true});const email='tab-return-'+randomUUID()+'@example.com',password=randomUUID(),created=await admin.auth.admin.createUser({email,password,email_confirm:true});if(created.error)throw created.error;const user=created.data.user.id,fixture={user,posts:[]};const save=()=>fs.writeFile(ledger,JSON.stringify(fixture),{mode:0o600});await save();
 const profile=await admin.from('profiles').insert({id:user,handle:'tab_'+user.slice(0,8),hints_seen:['capture','modes','thread','thumbs']});if(profile.error)throw profile.error;
 for(let n=0;n<3;n++){const post=sql(`select create_food_post('${user}',now(),'Tab test rice ${n}',100,'{"calories":100,"protein_g":2,"carbs_g":20,"fat_g":1,"micronutrients":[],"source_ref":"1"}'::jsonb);`);fixture.posts.push(post);await save();sql(`update posts set status='ready',render_time_zone='UTC' where id='${post}';insert into post_comments(post_id,author,body)values('${post}','model','Local test summary.');`);}
 sql(`insert into intake_logs(user_id,post_id,kind,amount,ml,label,source)values('${user}','${fixture.posts[0]}','water',250,250,'Water, mug','sheet');`);
 const cookies=[],client=createServerClient(e.NEXT_PUBLIC_SUPABASE_URL,e.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,{cookies:{getAll:()=>cookies,setAll:rows=>{for(const row of rows){const i=cookies.findIndex(c=>c.name===row.name);if(i<0)cookies.push(row);else cookies[i]=row;}}}});const login=await client.auth.signInWithPassword({email,password});if(login.error)throw login.error;await fs.writeFile(sessionFile,JSON.stringify(cookies),{mode:0o600});console.log('Owned synthetic fixture ready:3cards,one hydration row.');
}else throw Error('Use setup or cleanup');
